+  quota?: QuotaProvider;
+  dedup?: DeduplicationService;
+  fileWriteChecker?: FileWriteAuthChecker;
+  processingService?: ProcessingService;
+  namespace?: string;
+  defaultChunkSizeBytes?: number;
+  uploadSessionTtlSeconds?: number;
+  signedUrlTtlSeconds?: number;
