+          fileId,
+          versionId,
+          intent: options.intent,
+          state: 'ready',
+          mimeType: version.mimeType,
+          name: file.name,
+          size: version.size,
+          source: {
+            mode: 'original',
+            url: original.url,
+            headers: original.headers,
